import React, { useState, useEffect } from 'react';
import axios from 'axios';
import PostForm from './components/PostForm';
import PostList from './components/PostList';
import './App.css';

const API_BASE_URL = '/api/posts';

function App() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingPost, setEditingPost] = useState(null);

  const fetchPosts = async () => {
    try {
      setLoading(true);
      const response = await axios.get(API_BASE_URL);
      setPosts(response.data);
      setError(null);
    } catch (err) {
      setError('Failed to load posts. Please make sure the backend server is running.');
      console.error('Error fetching posts:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  const handleCreatePost = async (postData) => {
    try {
      const response = await axios.post(API_BASE_URL, postData);
      setPosts(prev => [response.data, ...prev]);
    } catch (err) {
      throw new Error(err.response?.data?.message || 'Failed to create post');
    }
  };

  const handleUpdatePost = async (id, postData) => {
    try {
      const response = await axios.put(`${API_BASE_URL}/${id}`, postData);
      setPosts(prev => prev.map(post => post._id === id ? response.data : post));
      setEditingPost(null);
    } catch (err) {
      throw new Error(err.response?.data?.message || 'Failed to update post');
    }
  };

  const handleDeletePost = async (id) => {
    if (!window.confirm('Are you sure you want to delete this post?')) return;

    try {
      await axios.delete(`${API_BASE_URL}/${id}`);
      setPosts(prev => prev.filter(post => post._id !== id));
    } catch (err) {
      throw new Error(err.response?.data?.message || 'Failed to delete post');
    }
  };

  const handleEditPost = (post) => {
    setEditingPost(post);
  };

  const handleCancelEdit = () => {
    setEditingPost(null);
  };

  return (
    <div className="app-bg">
      {/* Main Content Area */}
      <div className="d-flex flex-column min-vh-100 position-relative" style={{ zIndex: 1 }}>
        {/* Header */}
        <header className="glass-nav py-3 py-md-4 mb-3">
          <div className="container-xl">
            <div className="d-flex align-items-center justify-content-between">
              <div className="d-flex align-items-center gap-3">
                <div className="brand-icon">
                  <i className="bi bi-journal-richtext"></i>
                </div>
                <div>
                  <h1 className="h3 fw-bold mb-0 text-gradient">Blog Post Manager</h1>
                  <p className="text-muted small mb-0 d-none d-sm-block">Create, manage, and share your stories with ease</p>
                </div>
              </div>
              <span className="badge bg-white text-dark border shadow-sm px-3 py-2 rounded-pill d-none d-md-inline-flex align-items-center gap-2">
                <span className="spinner-grow spinner-grow-sm text-success" role="status" style={{ width: '8px', height: '8px' }}></span>
                Live Posts: {posts.length}
              </span>
            </div>
          </div>
        </header>

        {/* Main Content */}
        <main className="container-xl flex-grow-1 pb-5">
          {error && (
            <div className="alert alert-danger alert-dismissible fade show border-0 shadow-sm glass-card mb-4" role="alert">
              <div className="d-flex align-items-center gap-2">
                <i className="bi bi-exclamation-triangle-fill text-danger fs-5"></i>
                <div>{error}</div>
              </div>
              <button
                type="button"
                className="btn-close"
                onClick={() => setError(null)}
                aria-label="Close"
              ></button>
            </div>
          )}

          {/* Bootstrap 5 Responsive Grid (Form & List side-by-side on lg+, stacked on sm/md) */}
          <div className="row g-4 align-items-start">
            <div className="col-12 col-lg-5 col-xl-4 sticky-lg-custom">
              <PostForm
                onSubmit={handleCreatePost}
                onUpdate={handleUpdatePost}
                editingPost={editingPost}
                onCancelEdit={handleCancelEdit}
                loading={loading}
              />
            </div>

            <div className="col-12 col-lg-7 col-xl-8">
              <PostList
                posts={posts}
                loading={loading}
                onEdit={handleEditPost}
                onDelete={handleDeletePost}
              />
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

export default App;
